import React, { useEffect, useRef } from 'react';

const Game = () => {
  const squiggleRef = useRef(null);
  const gameOverRef = useRef(false);

  useEffect(() => {
    let mousePosition = { x: 0, y: 0 };
    const squiggleElement = document.getElementById('squiggle');

    if (!squiggleElement) return;

    // Handle mouse movement
    const handleMouseMove = (event) => {
      mousePosition = {
        x: event.clientX,
        y: event.clientY + window.scrollY
      };
    };

    // Check for collision between mouse and SVG
    const checkCollision = () => {
      if (gameOverRef.current) return;

      const path = squiggleElement.querySelector('path');
      if (!path) return;

      // Get the total length of the path
      const pathLength = path.getTotalLength();

      // Create an array of points along the path
      const points = [];
      for (let i = 0; i < pathLength; i += 10) { // Sample every 10 units
        const point = path.getPointAtLength(i);
        points.push({
          x: point.x,
          y: point.y
        });
      }

      // Check if mouse is near any point on the path
      const collisionDistance = 20; // Distance threshold for collision
      for (const point of points) {
        const dx = mousePosition.x - point.x;
        const dy = mousePosition.y - point.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < collisionDistance) {
          gameOverRef.current = true;
          // Trigger game over event
          const gameOverEvent = new CustomEvent('gameOver');
          document.dispatchEvent(gameOverEvent);
          break;
        }
      }
    };

    // Animation frame for smooth collision detection
    let animationFrameId;
    const animate = () => {
      checkCollision();
      if (!gameOverRef.current) {
        animationFrameId = requestAnimationFrame(animate);
      }
    };

    // Set up event listeners
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('gameOver', () => {
      const event = new CustomEvent('portfolioGameOver');
      document.dispatchEvent(event);
    });

    // Start animation
    animate();

    // Clean up
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
      gameOverRef.current = false;
    };
  }, []);

  return null; // This component doesn't render anything visible
};

export default Game;
